function moduleBadge(p){let id=currentSr(),n=0;if(p==='zero')n=zeroCount(id);if(p==='tasks')n=db.tasks.filter(x=>(!id||x.to===id||x.to==='ALL')&&x.status!=='Done').length;if(p==='sales')n=db.sales.filter(x=>(!id||x.sr===id)&&x.status!=='Delivered').length;if(p==='notifications')n=(db.notifications||[]).filter(x=>!x.read).length;return n?`<span class="moduleBadge">${n>999?'999+':n}</span>`:''}
function openGlobalSearch(){let o=document.createElement('div');o.className='globalSearchOverlay';o.innerHTML=`<div class="globalSearchBox"><div class="searchTop"><input id="globalSearchInput" autofocus placeholder="Search module, outlet, SKU, task..."><button id="closeGlobalSearch">×</button></div><div id="globalSearchResults"></div></div>`;document.body.appendChild(o);let inp=o.querySelector('#globalSearchInput'),res=o.querySelector('#globalSearchResults');o.querySelector('#closeGlobalSearch').onclick=()=>o.remove();function run(){let v=inp.value.trim().toLowerCase();if(!v){res.innerHTML='<div class="empty">Type to search.</div>';return}let out=[];mods.forEach(m=>{if((m[2]+' '+sub(m[1])).toLowerCase().includes(v))out.push(`<button class="searchResult" data-page="${m[1]}"><b>${m[2]}</b><span>${sub(m[1])}</span></button>`)});srIds().forEach(id=>outlets(id).forEach(x=>{if((x.name+' '+x.code+' '+x.category).toLowerCase().includes(v))out.push(`<div class="searchResult"><b>${esc(x.name)}</b><span>${esc(x.code)} · ${esc(x.category)} · ${short(sr(id).name)}</span></div>`)}));catalogueProducts().filter(x=>x.toLowerCase().includes(v)).slice(0,15).forEach(x=>out.push(`<div class="searchResult"><b>${esc(x)}</b><span>SKU / Product</span></div>`));db.tasks.filter(x=>(x.title+' '+(x.by||'')).toLowerCase().includes(v)).slice(0,10).forEach(x=>out.push(`<div class="searchResult"><b>${esc(x.title)}</b><span>Task · ${esc(x.by||'')}</span></div>`));res.innerHTML=out.slice(0,30).join('')||'<div class="empty">No result found.</div>';qa('.searchResult[data-page]',res).forEach(b=>b.onclick=()=>{o.remove();go(b.dataset.page)})}inp.oninput=run;setTimeout(()=>inp.focus(),50);run()}
function sub(p){return({dashboard:'Performance & graph',sales:'Order → Delivery',income:'Salary & earnings',incentive:'Target & progress',cpo:'Execution proof',route:'Daily focus plan',zero:'Outlet coverage',tasks:'Assignments',reports:'Analytics & export',proposals:'Forms & downloads',catalogue:'SKU master',control:'Admin & publishing',ai:'Ask your sales data'})[p]||''}
