function short(n=''){let a=n.split(' ');return a.length>2?a.slice(-2).join(' '):n}function bindScope(fn){qa('#scope button').forEach(b=>b.onclick=()=>{view=b.dataset.v;fn()})}

function dateVal(d){return d||today()}function inRange(x,f,t){return (!f||x>=f)&&(!t||x<=t)}
function rangeDelivered(id,f,t){return db.sales.filter(x=>x.status==='Delivered'&&(!id||x.sr===id)&&inRange(x.date,f,t)).reduce((a,x)=>a+(+x.deliveredAmount||0),0)}
function rangeQty(id,f,t){return db.sales.filter(x=>x.status==='Delivered'&&(!id||x.sr===id)&&inRange(x.date,f,t)).reduce((a,x)=>a+(+x.qty||0),0)}
function zeroOutlets(id,f=month()+'-01',t=today()){let ids=id?[id]:srIds(),rows=[];ids.forEach(sid=>outlets(sid).forEach(o=>rows.push({...o,sr:sid})));let covered=new Set(db.sales.filter(x=>x.status==='Delivered'&&inRange(x.date,f,t)&&ids.includes(x.sr)&&(+x.deliveredAmount>0||+x.qty>0)).map(x=>x.sr+'|'+(x.outletCode||x.outletName)));return rows.filter(o=>!covered.has(o.sr+'|'+(o.code||o.name)))}function zeroCount(id,f=month()+'-01',t=today()){return zeroOutlets(id,f,t).length}
const ffEditedImages=new WeakMap();
function fileData(file,max=1800000){return new Promise((res,rej)=>{if(!file)return res('');let edited=ffEditedImages.get(file);if(edited)return res(edited);if(file.size>max)return rej(new Error('File too large. Keep under '+Math.round(max/1000000*10)/10+' MB.'));let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}
function installUniversalImageEditor(){
 if(window.__ffImageEditorInstalled)return;window.__ffImageEditorInstalled=true;
 document.addEventListener('change',e=>{let input=e.target;if(!(input instanceof HTMLInputElement)||input.type!=='file'||!String(input.accept||'').includes('image'))return;let file=input.files&&input.files[0];if(!file)return;openUniversalImageEditor(file,input)},true)
}
function openUniversalImageEditor(file,input){
 let rd=new FileReader();rd.onload=()=>{let img=new Image();img.onload=()=>{
   let ov=document.createElement('div');ov.id='ffImageEditor';ov.style.cssText='position:fixed;inset:0;z-index:20000;background:rgba(0,0,0,.94);display:flex;align-items:center;justify-content:center;padding:14px';
   ov.innerHTML=`<div style="width:min(520px,96vw);background:#0b1217;border:1px solid #a6531f;border-radius:22px;padding:16px;box-shadow:0 20px 80px #000"><div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px"><b style="font-size:18px;color:#fff">Adjust Photo</b><button id="ffImgCancel" type="button" style="width:38px;height:38px;border-radius:50%;border:1px solid #374650;background:#141d23;color:#fff;font-size:22px">×</button></div><div style="height:min(54vh,430px);border:1px solid #33434c;border-radius:16px;overflow:hidden;background:#05080a;position:relative"><img id="ffImgPreview" style="position:absolute;left:50%;top:50%;max-width:none;max-height:none;transform-origin:center;user-select:none;pointer-events:none"></div><label style="display:block;color:#dce3e7;margin-top:13px">Zoom <input id="ffImgZoom" type="range" min="50" max="250" value="100" style="width:100%"></label><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><label style="color:#dce3e7">Left / Right <input id="ffImgX" type="range" min="-100" max="100" value="0" style="width:100%"></label><label style="color:#dce3e7">Up / Down <input id="ffImgY" type="range" min="-100" max="100" value="0" style="width:100%"></label></div><div style="font-size:11px;color:#98a5ad;margin:8px 0 12px">Zoom out করলে পুরো ছবি রাখা যাবে। Zoom/position যেভাবে রাখবেন, upload-এ ঠিক সেই framing save হবে।</div><button id="ffImgUse" type="button" style="width:100%;border:0;border-radius:14px;padding:13px;background:linear-gradient(135deg,#ff9b2f,#ff6410);color:#111;font-weight:900;font-size:15px">USE THIS PHOTO</button></div>`;
   document.body.appendChild(ov);let pv=ov.querySelector('#ffImgPreview'),z=ov.querySelector('#ffImgZoom'),xx=ov.querySelector('#ffImgX'),yy=ov.querySelector('#ffImgY');pv.src=rd.result;
   const fit=()=>{let box=pv.parentElement,bw=box.clientWidth,bh=box.clientHeight,base=Math.min(bw/img.width,bh/img.height),scale=base*(+z.value/100);pv.style.width=(img.width*scale)+'px';pv.style.height=(img.height*scale)+'px';pv.style.transform=`translate(calc(-50% + ${+xx.value*bw/200}px),calc(-50% + ${+yy.value*bh/200}px))`};[z,xx,yy].forEach(a=>a.oninput=fit);requestAnimationFrame(fit);
   ov.querySelector('#ffImgCancel').onclick=()=>{input.value='';ov.remove()};
   ov.querySelector('#ffImgUse').onclick=()=>{let box=pv.parentElement,W=Math.max(720,Math.round(box.clientWidth*2)),H=Math.max(720,Math.round(box.clientHeight*2)),c=document.createElement('canvas');c.width=W;c.height=H;let ctx=c.getContext('2d');ctx.fillStyle='#05080a';ctx.fillRect(0,0,W,H);let base=Math.min(W/img.width,H/img.height),scale=base*(+z.value/100),dw=img.width*scale,dh=img.height*scale,cx=W/2+(+xx.value*W/200),cy=H/2+(+yy.value*H/200);ctx.drawImage(img,cx-dw/2,cy-dh/2,dw,dh);let data=c.toDataURL('image/jpeg',.9);ffEditedImages.set(file,data);ov.remove()}
 };img.src=rd.result};rd.readAsDataURL(file)
}
