 const skuOptions=master.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');
 shell(back('Product Incentive')+(isMgr()?scopeBar():'')+`<div>${cards}</div>${isMgr()?`<div class="card"><div class="cardTitle">Publish Incentive Poster</div><div class="notice">SKU source = Catalogue. Catalogue-এ নতুন product add করলে এখানে automatically পাওয়া যাবে। একই poster-এর নিচে Single SKU বা Combo SKU—একাধিক incentive group add করা যাবে।</div><form class="form" id="incForm"><label>Campaign / Poster Name<input name="name" required></label><label>Assign To<select name="sr"><option>ALL</option>${srIds().map(x=>`<option value="${x}">${sr(x).name}</option>`).join('')}</select></label><label>One Poster / Artwork<input name="image" type="file" accept="image/*"></label><div id="incGroups"></div><button type="button" class="secondary" id="addIncGroup">+ ADD SINGLE / COMBO INCENTIVE</button><button class="primary premiumBtn">PUBLISH INCENTIVE</button></form></div>`:''}`);
