async function proposals(){
 currentPage='proposals';localStorage.setItem('ffh_last_page',currentPage);
 let cloud=[];
 try{
  let {data,error}=await FFH_SUPABASE.from('ffh_proposals').select('id,name,category,logo_url,file_url,filename,created_date').order('created_at',{ascending:false});
  if(!error&&Array.isArray(data)) cloud=data.map(x=>({id:String(x.id),name:x.name||'Proposal',category:x.category||'Proposal Form',logo:x.logo_url||'',file:x.file_url||'',filename:x.filename||'',date:x.created_date||today(),cloud:true}));
 }catch(_){ cloud=(db.proposals||[]).filter(x=>x.cloud); }
 const norm=v=>String(v||'').toUpperCase().replace(/[^A-Z0-9]+/g,'');
 const aliases={
  '02':['KKSUPERMART','KKSUPERMARKET'], '03':['NSKGROCER','NSK'], '05':['AEONBIG','AEONBIGMALAYSIA'],
  '07':['LOTUSSMALAYSIA','LOTUSMALAYSIA','LOTUSS'], '15':['BIGBENSINDEPENDENTGROCER','BIG'],
  '16':['TFVALUEMART','TFVALUE'], '21':['MERCEARIANEIGHBOURHOODGROCER','MERCEARIA'],
  '23':['KECOMART','KECOMARKET'], '32':['MRDIY','MRDIYALWAYSLOWPRICES']
 };
 const matchCloud=t=>cloud.find(x=>{let n=norm(x.name), a=[norm(t.name),...(aliases[t.key]||[])];return a.some(z=>z&&(n===z||n.includes(z)||z.includes(n)))});
 const defaults=FFH_PROPOSAL_TEMPLATES.map(t=>{let c=matchCloud(t);return {id:c?.id||('TPL'+t.key),templateKey:t.key,name:t.name,category:'Proposal Form',logo:t.asset,file:c?.file||'',filename:c?.filename||'',date:c?.date||'',cloud:!!c?.cloud,isTemplate:true}});
 const matched=new Set(defaults.filter(x=>x.cloud).map(x=>String(x.id)));
 const extras=cloud.filter(x=>!matched.has(String(x.id))).map(x=>({...x,isTemplate:false}));
 let list=[...defaults,...extras];
 db.proposals=list; try{save()}catch(_){}
 const actionHtml=x=>x.file?`<div class="ffProposalActions"><button class="secondary ffPropView" data-id="${esc(x.id)}">👁 VIEW PDF</button><button class="primary ffPropDownload" data-id="${esc(x.id)}">⬇ DOWNLOAD PDF</button>${isMgr()?`<button class="secondary ffPropEdit" data-id="${esc(x.id)}">✎ EDIT PDF</button>`:''}</div>`:`<div class="ffProposalActions ffNoPdf"><span>PDF not uploaded yet</span>${isMgr()?`<button class="primary ffPropEdit" data-id="${esc(x.id)}">＋ UPLOAD PDF</button>`:''}</div>`;
 const cards=list.map(x=>`<article class="ffProposalStrip" data-id="${esc(x.id)}">${isMgr()&&!x.isTemplate?`<button class="ffProposalDots delProposal" data-id="${esc(x.id)}" title="Delete">⋮</button>`:''}<div class="ffProposalVisual"><img loading="lazy" decoding="async" src="${esc(x.logo)}" alt="${esc(x.name)} Proposal Form" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"><div class="ffProposalGenerated" style="display:none"><b>${esc(x.name)}</b><span>PROPOSAL FORM</span></div></div>${actionHtml(x)}</article>`).join('');
 shell(back('Proposal Form')+`<section class="ffProposalPage"><div class="ffProposalHead"><div><h1>Proposal <span>Form</span></h1><p>32 READY FORMS · VIEW · DOWNLOAD</p></div>${isMgr()?`<button class="primary ffTopAction" id="addProposalTop">＋ Add New</button>`:''}</div><div class="ffProposalStack">${cards}</div><div class="ffBottomQuote ffMotivationFooter"><span>“ Ready Forms · Faster Action · Bigger Business ”</span></div></section>`);bindBack();
 const byId=id=>list.find(x=>String(x.id)===String(id));
 const downloadPdf=async x=>{if(!x?.file)return alert('PDF not uploaded yet.');try{let r=await fetch(x.file);if(!r.ok)throw Error('HTTP '+r.status);let b=await r.blob(),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=x.filename||((x.name||'proposal')+'.pdf');document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1500)}catch(_){let a=document.createElement('a');a.href=x.file;a.target='_blank';a.rel='noopener';a.click()}};
 qa('.ffPropView').forEach(b=>b.onclick=()=>{let x=byId(b.dataset.id);if(x?.file)window.open(x.file,'_blank','noopener');else alert('PDF not uploaded yet.')});
 qa('.ffPropDownload').forEach(b=>b.onclick=()=>downloadPdf(byId(b.dataset.id)));
 const uploadPdfModal=(x=null)=>{let isTemplate=!!x?.isTemplate,o=document.createElement('div');o.className='globalSearchOverlay';o.innerHTML=`<div class="globalSearchBox ffPremiumModal"><button type="button" class="ffModalBack">← Back</button><div class="cardTitle">${x?'Update':'Add'} Proposal PDF</div><form class="form" id="propForm"><label>Chain / Proposal Name<input name="name" value="${esc(x?.name||'')}" ${isTemplate?'readonly':''} placeholder="e.g. New Chain" required></label>${!isTemplate?`<label>Proposal Banner Image${x?' (optional — choose to replace)':''}<input name="logo" type="file" accept="image/*" ${x?'':'required'}></label>`:''}<label>PDF File<input name="pdf" type="file" accept="application/pdf" required></label><div class="notice">${isTemplate?'The premium banner is already fixed. Upload only the PDF.':'Upload one premium banner and its PDF. It will be saved to cloud.'}</div><button class="primary">${x?'UPDATE':'UPLOAD'} & PUBLISH</button><button type="button" class="secondary ffCloseModal">CANCEL</button></form></div>`;document.body.appendChild(o);let close=()=>o.remove();o.querySelector('.ffModalBack').onclick=close;o.querySelector('.ffCloseModal').onclick=close;o.onclick=e=>{if(e.target===o)close()};o.querySelector('#propForm').onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target),file=fd.get('pdf'),btn=e.target.querySelector('button.primary');try{btn.disabled=true;btn.textContent='UPLOADING…';let base=`proposals/${user.id}`,pdf=await ffhUploadPublicFile(file,base+'/pdf'),lg=x?.isTemplate?'':(x?.logo||'');if(!isTemplate){let logo=fd.get('logo');if(logo?.size)lg=await ffhUploadPublicFile(logo,base+'/covers')}let row={name:String(fd.get('name')||x?.name||'Proposal'),category:'Proposal Form',logo_url:lg,file_url:pdf,filename:file.name,created_date:today()};if(x?.cloud){let {error}=await FFH_SUPABASE.from('ffh_proposals').update(row).eq('id',x.id);if(error)throw error}else{let id=(crypto?.randomUUID?crypto.randomUUID():'P'+Date.now()+Math.random().toString(36).slice(2));let {error}=await FFH_SUPABASE.from('ffh_proposals').insert({id,...row});if(error)throw error}close();await proposals()}catch(err){alert('Proposal upload failed: '+(err?.message||err));btn.disabled=false;btn.textContent=(x?'UPDATE':'UPLOAD')+' & PUBLISH'}}};
 qa('.ffPropEdit').forEach(b=>b.onclick=()=>uploadPdfModal(byId(b.dataset.id)));
 if(q('#addProposalTop'))q('#addProposalTop').onclick=()=>uploadPdfModal(null);
 qa('.delProposal').forEach(b=>b.onclick=async e=>{e.preventDefault();e.stopPropagation();if(!confirm('Delete this proposal?'))return;let x=byId(b.dataset.id);if(x?.cloud){let {error}=await FFH_SUPABASE.from('ffh_proposals').delete().eq('id',x.id);if(error)return alert('Delete failed: '+error.message)}await proposals()});
}
function reports(){let names=['Executive Summary','SR Performance','Daily Sales','Delivered Sales','Outlet Wise','SKU Wise','Targets & Shortfall','Income Breakdown','Sales Commission','Product Incentives','Other Incentives','Zero Sales','CPO Execution','Promotion Execution','Route & Visits'];shell(back('Reports & Full Export')+`<div class="range"><input id="rf" type="date" value="${month()+'-01'}"><input id="rt" type="date" value="${today()}"></div><div class="card">${names.map((x,i)=>`<button class="listBtn reportBtn" data-r="${i}"><span><i class="ico">▥</i>${x}</span><b>›</b></button>`).join('')}</div><button class="primary premiumBtn" id="xls">DOWNLOAD FULL EXCEL WORKBOOK</button>`);bindBack();qa('.reportBtn').forEach(b=>b.onclick=()=>{navStack.push({name:'reports',view});currentPage='report:'+b.dataset.r;reportView(names[+b.dataset.r])});q('#xls').onclick=exportWorkbook}
function reportIncomeFor(id,f,t){let setup=db.incomeSetup[id]||{},basic=+(setup.basic??rules.basic??0),fuel=+(setup.fuel??rules.fuel??0),house=+(setup.houseRent??rules.houseRent??0),d=rangeDelivered(id,f,t),m=(f||month()+'-01').slice(0,7),tar=target(id,m),a=tar?d/tar:0,comm=a<.8?d*.005:a<=1?d*.01:tar*.01+Math.max(0,d-tar)*.02,food=d>=rules.foodThreshold?rules.foodHigh:rules.foodLow,adj=(db.adjustments||[]).filter(x=>x.sr===id&&x.month===m),pos=adj.filter(x=>x.kind!=='Penalty').reduce((s,x)=>s+(+x.amount||0),0),pen=adj.filter(x=>x.kind==='Penalty').reduce((s,x)=>s+(+x.amount||0),0);return{basic,fuel,house,food,d,tar,comm,pos,pen,total:basic+fuel+house+(+food||0)+comm+pos-pen}}
function reportRows(name){let id=currentSr(),f=q('#rf')?.value||month()+'-01',t=q('#rt')?.value||today(),ids=id?[id]:srIds(),sales=(db.sales||[]).filter(x=>ids.includes(x.sr)&&inRange(x.date,f,t)),del=sales.filter(x=>x.status==='Delivered'),m=f.slice(0,7);
 if(name==='Executive Summary'){let dv=del.reduce((a,x)=>a+(+x.deliveredAmount||0),0),tar=ids.reduce((a,sid)=>a+target(sid,m),0),qty=del.reduce((a,x)=>a+(+x.qty||0),0);return [['Metric','Value'],['Period',f+' to '+t],['Assigned SR',ids.length],['Monthly Target RM',tar],['Delivered Sales RM',dv],['Achievement %',tar?+(dv/tar*100).toFixed(2):0],['Shortfall RM',Math.max(0,tar-dv)],['Delivered Qty',qty],['Pending Orders',sales.filter(x=>x.status!=='Delivered').length],['Zero Sales Outlets',zeroCount(id,f,t)]]}
 if(name==='SR Performance')return [['SR','Target RM','Delivered RM','Achievement %','Shortfall RM','Delivered Qty','Zero Outlets'],...ids.map(sid=>{let d=rangeDelivered(sid,f,t),tar=target(sid,m);return[sr(sid)?.name||sid,tar,d,tar?+(d/tar*100).toFixed(2):0,Math.max(0,tar-d),rangeQty(sid,f,t),zeroCount(sid,f,t)]})];
 if(name==='Daily Sales')return [['Date','SR','Outlet Code','Outlet','SKU','Qty','Order RM','Status'],...sales.map(x=>[x.date,sr(x.sr)?.name||x.sr,x.outletCode||'',x.outletName||'',x.sku||'',+x.qty||0,+x.orderAmount||0,x.status||''])];
 if(name==='Delivered Sales')return [['Date','SR','Outlet Code','Outlet','SKU','Qty','Order RM','Delivered RM','Delivered At'],...del.map(x=>[x.date,sr(x.sr)?.name||x.sr,x.outletCode||'',x.outletName||'',x.sku||'',+x.qty||0,+x.orderAmount||0,+x.deliveredAmount||0,x.deliveredAt||''])];
 if(name==='Outlet Wise'){let rr=[];ids.forEach(sid=>outlets(sid).forEach(o=>{let rows=del.filter(x=>x.sr===sid&&(x.outletCode===o.code||x.outletName===o.name)),v=rows.reduce((a,x)=>a+(+x.deliveredAmount||0),0),qty=rows.reduce((a,x)=>a+(+x.qty||0),0);rr.push([sr(sid)?.name||sid,o.code,o.name,o.category,qty,v,v>0?'COVERED':'ZERO'])}));return [['SR','Outlet Code','Outlet Name','Category','Delivered Qty','Delivered RM','Status'],...rr]}
 if(name==='SKU Wise'){let map={};del.forEach(x=>{let k=x.sr+'|'+(x.sku||'Unspecified'),r=map[k]||(map[k]={sr:x.sr,sku:x.sku||'Unspecified',qty:0,order:0,delivered:0,count:0});r.qty+=+x.qty||0;r.order+=+x.orderAmount||0;r.delivered+=+x.deliveredAmount||0;r.count++});return [['SR','SKU','Delivered Orders','Qty / Carton','Order RM','Delivered RM'],...Object.values(map).sort((a,b)=>b.delivered-a.delivered).map(r=>[sr(r.sr)?.name||r.sr,r.sku,r.count,r.qty,r.order,r.delivered])]}
 if(name==='Targets & Shortfall')return [['SR','Month','Target RM','Delivered RM','Achievement %','Shortfall RM'],...ids.map(sid=>{let d=rangeDelivered(sid,f,t),tar=target(sid,m);return[sr(sid)?.name||sid,m,tar,d,tar?+(d/tar*100).toFixed(2):0,Math.max(0,tar-d)]})];
 if(name==='Income Breakdown')return [['SR','Basic RM','Fuel RM','House Rent RM','Food RM','Commission RM','Other Incentive RM','Penalty RM','Estimated Net RM'],...ids.map(sid=>{let r=reportIncomeFor(sid,f,t);return[sr(sid)?.name||sid,r.basic,r.fuel,r.house,r.food,+r.comm.toFixed(2),r.pos,r.pen,+r.total.toFixed(2)]})];
 if(name==='Sales Commission')return [['SR','Target RM','Delivered RM','Achievement %','Commission RM','Rule'],...ids.map(sid=>{let r=reportIncomeFor(sid,f,t),a=r.tar?r.d/r.tar:0;return[sr(sid)?.name||sid,r.tar,r.d,r.tar?+(a*100).toFixed(2):0,+r.comm.toFixed(2),a<.8?'0.5%':a<=1?'1%':'1% target + 2% excess']})];
 if(name==='Product Incentives'){let rows=[];(db.incentives||[]).filter(c=>c.sr==='ALL'||ids.includes(c.sr)).forEach(c=>{let cids=c.sr==='ALL'?ids:[c.sr],groups=Array.isArray(c.groups)&&c.groups.length?c.groups:[{name:c.name||'SKU',skus:Array.isArray(c.skus)?c.skus:(c.sku?[c.sku]:[]),target:+c.target||0,reward:+c.reward||0}];cids.forEach(sid=>groups.forEach(g=>{let got=del.filter(x=>x.sr===sid&&(g.skus||[]).includes(x.sku)).reduce((a,x)=>a+(+x.qty||0),0),tar=+g.target||0;rows.push([c.name||'',sr(sid)?.name||sid,g.name||'',(g.skus||[]).join(' + '),tar,got,Math.max(0,tar-got),+g.reward||0,tar&&got>=tar?'ACHIEVED':'IN PROGRESS'])}))});return [['Campaign','SR','Group','SKU(s)','Target Carton','Delivered Carton','Remaining','Reward RM','Status'],...rows]}
 if(name==='Other Incentives'){let rows=(db.adjustments||[]).filter(x=>ids.includes(x.sr)&&x.kind!=='Penalty'&&x.kind!=='Product Incentive'&&x.month===m);return [['Month','SR','Type','Amount RM','Reason','Given By'],...rows.map(x=>[x.month,sr(x.sr)?.name||x.sr,x.kind,+x.amount||0,x.reason||'',x.by||''])]}
 if(name==='Zero Sales')return [['SR','Outlet Code','Outlet Name','Category','Status'],...zeroOutlets(id,f,t).map(o=>[sr(o.sr)?.name||o.sr,o.code,o.name,o.category,'ZERO'])];
 if(name==='CPO Execution'||name==='Promotion Execution'){let ty=name.startsWith('CPO')?'CPO':'Promotion',rows=(db.cpo||[]).filter(x=>ids.includes(x.sr)&&inRange(x.date,f,t)).filter(x=>{let c=(db.cpoCampaigns||[]).find(z=>z.id===x.campaignId);return String(c?.type||x.type||'').toLowerCase()===ty.toLowerCase()});return [['Date','Campaign','SR','Outlet Code','Outlet','Category','Status','Remarks','Photo Saved'],...rows.map(x=>{let c=(db.cpoCampaigns||[]).find(z=>z.id===x.campaignId)||{};return[x.date,c.title||'',sr(x.sr)?.name||x.sr,x.outletCode||'',x.outlet||'',x.category||'',x.status||'',x.remarks||'',x.photo?'YES':'NO']})]}
 if(name==='Route & Visits'){let rows=[];ids.forEach(sid=>{let done=new Set(del.filter(x=>x.sr===sid).map(x=>x.outletCode||x.outletName));outlets(sid).forEach(o=>rows.push([sr(sid)?.name||sid,o.code,o.name,o.category,done.has(o.code||o.name)?'COVERED':'PENDING / ZERO']))});return [['SR','Outlet Code','Outlet','Category','Coverage Status'],...rows]}
 return [['Info'],['No report data']]
}
function reportView(name){let rows=reportRows(name);shell(back(name)+`<div class="card reportTable"><table>${rows.map((r,i)=>`<tr>${r.map(c=>i?`<td>${esc(c)}</td>`:`<th>${esc(c)}</th>`).join('')}</tr>`).join('')}</table></div>`);bindBack()}
function exportWorkbook(){let sheets=['Executive Summary','SR Performance','Daily Sales','Delivered Sales','Outlet Wise','SKU Wise','Targets & Shortfall','Income Breakdown','Sales Commission','Product Incentives','Other Incentives','Zero Sales','CPO Execution','Promotion Execution','Route & Visits'];let xml=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">`+sheets.map(n=>`<Worksheet ss:Name="${xmlEsc(n.slice(0,31))}"><Table>`+reportRows(n).map(r=>`<Row>`+r.map(c=>`<Cell><Data ss:Type="${typeof c==='number'?'Number':'String'}">${xmlEsc(c)}</Data></Cell>`).join('')+`</Row>`).join('')+`</Table></Worksheet>`).join('')+`</Workbook>`;let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([xml],{type:'application/vnd.ms-excel'}));a.download='FieldForce-Full-'+today()+'.xls';a.click()}
