function aiQuickQuestions(){return lang==='bn'?[['▥','আমার সেলস কেমন?','আজ, এই সপ্তাহ বা এই মাস'],['◎','আমার টার্গেট প্রোগ্রেস?','টার্গেট বনাম অ্যাচিভমেন্ট'],['▣','কোন আউটলেটে ফোকাস দেব?','পারফরম্যান্স অনুযায়ী সাজেশন'],['▤','CPO / Promotion স্ট্যাটাস','অর্ডার, ডেলিভারি ও এক্সিকিউশন'],['⌖','আজকের রুট প্ল্যান দেখাও','ভিজিট এবং কভারেজ'],['$','আমার ইনকাম আপডেট','বেতন, ইনসেনটিভ ও বোনাস']]:[['▥','How are my sales?','Today, this week or this month'],['◎','My target progress?','Target versus achievement'],['▣','Which outlets need focus?','Suggestions from performance'],['▤','CPO / Promotion status','Order, delivery and execution'],['⌖','Show today’s route plan','Visits and coverage'],['$','My income update','Salary, incentive and bonus']]}
function toggleAIPopup(){if(q('#aiPopup'))closeAIPopup();else openAIPopup()}
function openAIPopup(){q('#aiPopup')?.remove();q('#aiHello')?.remove();let welcome=aiWelcomeText(),qs=aiQuickQuestions();let o=document.createElement('div');o.id='aiPopup';o.className='aiPopupOverlay aiFloatingOverlay';o.innerHTML=`<section class="aiPopupPanel"><button class="aiVoiceStop" id="aiVoiceStop" title="${lang==='bn'?'ভয়েস বন্ধ':'Mute voice'}">🔇</button><div class="aiPopupLeft"><div class="growTogether">Let’s<br>Grow<br>Together!</div><div class="aiSideBrand"><img src="fieldforce-logo.jpg" alt="FieldForce Hub logo"><b>FieldForce Hub</b><small>Sales | Delivery | Performance | Growth</small></div><div class="aiIdentityTop"><strong>Mehedi Alim Ayon</strong><small>Key Account Manager</small></div><div class="aiPortraitFade"><img src="ayon-full-transparent.png" onerror="this.src='330441.png'" class="aiFullPortrait"></div><div class="aiMotto">Smart People<br>Stronger Team<br><b>Bigger Tomorrow</b></div></div><div class="aiPopupMain"><div class="aiPopupTitle"><span>✦</span><div><h2>AYON <b>AI</b></h2><p>${lang==='bn'?'আপনার Sales Intelligence Assistant':'Your Sales Intelligence Assistant'}</p></div></div><div class="aiStatus"><i></i> Online <span>|</span> Data-aware <span>|</span> Permission-aware <span>|</span> Voice enabled</div><div class="aiWelcome compactWelcome"><b>✦</b><p><strong>${esc(welcome)}</strong><small>${esc(aiShortIntro())}</small></p></div><h3>⚡ ${lang==='bn'?'আপনি যা জানতে পারেন:':'You can ask:'}</h3><div class="aiQuickGrid">${qs.map(x=>`<button class="aiQuick" data-q="${esc(x[1])}"><i>${x[0]}</i><span><b>${esc(x[1])}</b><small>${esc(x[2])}</small></span><em>›</em></button>`).join('')}</div><div class="aiPopupChat" id="aiPopupChat"></div><div class="aiPopupComposer"><button id="aiPopupMic">🎙</button><input id="aiPopupAsk" placeholder="${lang==='bn'?'AYON AI-কে জিজ্ঞেস করুন...':'Ask AYON AI...'}"><button id="aiPopupSend">➤</button></div><small class="aiDisclaimer">♢ AI may not be 100% accurate. Please verify critical information.</small></div></section>`;document.body.appendChild(o);q('#aiVoiceStop').onclick=stopAIVoice;qa('.aiQuick',o).forEach(b=>b.onclick=()=>{q('#aiPopupAsk').value=b.dataset.q;askAIPopup()});q('#aiPopupSend').onclick=askAIPopup;q('#aiPopupAsk').onkeydown=e=>e.key==='Enter'&&askAIPopup();setupPopupMic();}
function setupPopupMic(){let B=q('#aiPopupMic');if(!B)return;let SR=window.SpeechRecognition||window.webkitSpeechRecognition;const note=msg=>{let c=q('#aiPopupChat');if(c){c.innerHTML+=`<div class="bubble bot voiceNote">${esc(msg)}</div>`;c.scrollTop=c.scrollHeight}};if(!SR){B.onclick=()=>note('স্যার, এই ব্রাউজারে voice-to-text পাওয়া যাচ্ছে না। Chrome-এ microphone permission Allow করে আবার চেষ্টা করুন।');return}let r=null,busy=false;const build=()=>{r=new SR();r.lang=lang==='bn'?'bn-BD':'en-US';r.interimResults=false;r.continuous=false;r.maxAlternatives=3;r.onstart=()=>{busy=true;B.classList.add('listening');B.textContent='●'};r.onresult=e=>{let t='';for(let i=e.resultIndex;i<e.results.length;i++){if(e.results[i].isFinal)t+=(t?' ':'')+e.results[i][0].transcript}t=t.trim();let I=q('#aiPopupAsk');if(I&&t){I.value=t;setTimeout(()=>askAIPopup(),80)}};r.onerror=e=>{busy=false;B.classList.remove('listening');B.textContent='🎙';if(e.error==='not-allowed'||e.error==='service-not-allowed')note('স্যার, Microphone permission Allow করুন, তারপর আবার mic চাপুন।');else if(e.error==='no-speech')note('স্যার, কথাটা শুনতে পাইনি। Mic-এর কাছে একটু স্পষ্ট করে আবার বলুন।');else if(e.error==='network')note('স্যার, ফোনের speech service network পাচ্ছে না। Internet on রেখে আবার mic চাপুন।');else if(e.error!=='aborted')note('স্যার, voice input সমস্যা: '+e.error)};r.onend=()=>{busy=false;B.classList.remove('listening');B.textContent='🎙'}};B.onclick=()=>{if(busy){try{r.stop()}catch(_){}return}try{build();r.start()}catch(e){note('স্যার, microphone চালু হয়নি। Browser microphone permission চেক করুন।')}}}
function playAIPop(){try{let C=window.AudioContext||window.webkitAudioContext;if(!C)return;let c=new C(),o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.setValueAtTime(430,c.currentTime);o.frequency.exponentialRampToValueAtTime(760,c.currentTime+.09);g.gain.setValueAtTime(.0001,c.currentTime);g.gain.exponentialRampToValueAtTime(.12,c.currentTime+.015);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+.14);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.15)}catch(_){}}
function homeAIHelloText(){let n=displayFirstName(),g=greetingNow();if(lang==='bn')return `হাই ${n} স্যার! ${g}`;return `Hi ${n} Sir! ${g}`}
function showAIHello(){q('#aiHello')?.remove();let h=document.createElement('div');h.id='aiHello';h.className='aiHelloBubble';h.innerHTML=`<strong>${esc(homeAIHelloText())}</strong><small>${lang==='bn'?'আমি আপনার Sales Assistant — AYON AI':'I am your Sales Assistant — AYON AI'}</small>`;document.body.appendChild(h);playAIPop();requestAnimationFrame(()=>h.classList.add('show'));setTimeout(()=>{h.classList.remove('show');setTimeout(()=>h.remove(),220)},3000)}
let aiWelcomeTimer=0,aiWelcomeStamp=0;
